{"source":"def investigate(context, acquire):
    actions = context.get('actions')
    if actions is None:
        actions = []
    sqlite = acquire('sqlite')
    connection = sqlite.connect(':memory:')
    cursor = connection.cursor()
    cursor.execute('CREATE TABLE t (id INTEGER PRIMARY KEY AUTOINCREMENT)')
    for action in actions:
        operation = action.get('op')
        if operation == 'put':
            cursor.execute('INSERT INTO t (id) VALUES (?)', (action.get('id'),))
        elif operation == 'delete':
            cursor.execute('DELETE FROM t WHERE id = ?', (action.get('id'),))
        elif operation == 'begin':
            cursor.execute('BEGIN')
        elif operation == 'commit':
            cursor.execute('COMMIT')
        elif operation == 'rollback':
            cursor.execute('ROLLBACK')
    cursor.execute('INSERT INTO t DEFAULT VALUES')
    cursor.execute('SELECT id FROM t WHERE rowid = (SELECT max(rowid) FROM t)')
    result = cursor.fetchone()[0]
    connection.close()
    return int(result)
","scope":"Repairs the native SQLite AUTOINCREMENT diagnostic by replacing the unsupported cursor.lastrowid probe with a SELECT over the maximum rowid on the same connection. The schema, action handling, transaction semantics, and final unkeyed insert are unchanged.","change":"Removed the unsupported lastrowid method call. After the final INSERT INTO t DEFAULT VALUES, query SELECT id FROM t WHERE rowid = (SELECT max(rowid) FROM t), fetch the single row, and return its id as an integer. This preserves SQLite AUTOINCREMENT behavior, including rollback restoring the sequence and deletion not lowering the next allocated id."}
